export const BODY: string = "\n<p>ری سائز اور کمپریس دونوں فائل کو چھوٹا کرتے ہیں، مگر الگ طریقوں سے۔ ری سائز پکسلز کم کرتا ہے، کمپریشن پکسلز بچا کر وزن کم کرتی ہے۔</p>\n<p>فرق نہ جاننے سے غلط فیصلہ ہوتا ہے: صرف کمپریس کرنے سے 4000 پکسلز والی تصویر 4000 پکسلز ہی رہتی ہے، اور صرف ری سائز کرنے سے فائل پھر بھی بھاری رہ سکتی ہے۔</p>\n<p>یہ مضمون دونوں کا موازنہ کرتا ہے، اصل عددوں سے مثال دیتا ہے، اور بتاتا ہے کہ کب صرف ایک کریں، کب دونوں کریں، اور کس ترتیب میں کریں۔ ری سائز کے لیے <a href=\"/ur/tasveer-resize-karein/\">امیج ری سائزر</a> اور کمپریس کے لیے <a href=\"/ur/tasveer-compress-karein-100kb-tak/\">100KB کمپریسر</a> استعمال کریں۔</p>\n<h2 id=\"what-resizing-does\">ری سائز کیا کرتا ہے</h2>\n<p>ری سائز تصویر کی چوڑائی اور اونچائی پکسلز میں بدلتا ہے۔ 4000 پکسلز والی تصویر کو 1000 پکسلز تک چھوٹا کرنا ری سائز ہے۔</p>\n<p>ری سائز سے پکسلز کم ہوتے ہیں، اس لیے فائل بھی ہلکی ہو جاتی ہے۔ لیکن فائل کا وزن صرف پکسلز پر نہیں، کمپریشن پر بھی منحصر ہے۔</p>\n<p>ری سائز تصویر کا کوئی حصہ نہیں کاٹتا، پوری تصویر سکڑتی ہے۔ موضوع کا ہر حصہ بچتا ہے، صرف چھوٹا ہو جاتا ہے۔</p>\n<h2 id=\"what-compressing-does\">کمپریس کیا کرتا ہے</h2>\n<p>کمپریشن پکسلز بچا کر فائل کا وزن کم کرتی ہے۔ 4000 پکسلز والی تصویر کمپریس ہو کر بھی 4000 پکسلز کی رہتی ہے، صرف ہلکی ہو جاتی ہے۔</p>\n<p>کمپریشن تفصیل پھینک کر فائل چھوٹی کرتی ہے۔ ہلکی کمپریشن میں فرق نظر نہیں آتا، بھاری میں رنگوں کی پٹیاں نظر آنے لگتی ہیں۔</p>\n<p>کمپریشن تصویر کا سائز نہیں بدلتی، صرف اس کا وزن بدلتی ہے۔ اسکرین پر تصویر اتنی ہی بڑی نظر آتی ہے۔</p>\n<h2 id=\"side-by-side\">ری سائز بمقابلہ کمپریس، ساتھ ساتھ</h2>\n<p>ری سائز پکسلز بدلتا ہے اور کمپریشن وزن بدلتی ہے۔ ری سائز سے تصویر چھوٹی نظر آتی ہے، کمپریشن سے تصویر ویسی ہی نظر آتی ہے، صرف فائل ہلکی ہوتی ہے۔</p>\n<p>دونوں کو ایک ساتھ استعمال کرنا بہترین ہے: پہلے ری سائز کریں، پھر کمپریس کریں۔ اس ترتیب سے فائل سب سے زیادہ ہلکی ہوتی ہے۔</p>\n<p>صرف ایک کرنا اکثر کافی نہیں ہوتا۔ بڑی تصویر کو صرف کمپریس کرنا اسے بڑا ہی رکھتا ہے، اور صرف ری سائز کرنا اسے بھاری رکھ سکتا ہے۔</p>\n<h2 id=\"a-worked-example\">اصل عددوں سے مثال</h2>\n<p>4000 پکسلز والی 8MB تصویر کو 1000 پکسلز تک ری سائز کرنے سے وہ 500KB بن جاتی ہے۔ پھر اسے 80 معیار پر کمپریس کرنے سے وہ 150KB بن جاتی ہے۔</p>\n<p>صرف کمپریس کرنے سے وہی تصویر 8MB سے 2MB بنتی ہے، جو اب بھی بہت بڑی ہے۔ صرف ری سائز کرنے سے وہ 500KB بنتی ہے، جو اب بھی بھاری ہے۔</p>\n<p>دونوں مل کر 8MB کو 150KB بناتے ہیں، یعنی پچاس گنا چھوٹی۔ یہی دونوں کا اصل فائدہ ہے۔</p>\n<h2 id=\"how-each-affects-file-size\">ہر قدم فائل سائز پر کیسے اثر ڈالتا ہے</h2>\n<p>ری سائز سے فائل سائز پکسلز کے تناسب سے کم ہوتا ہے: آدھے پکسلز کا مطلب تقریباً چوتھائی فائل۔ کمپریشن سے فائل سائز معیار کے تناسب سے کم ہوتا ہے۔</p>\n<p>دونوں کا اثر جمع ہوتا ہے، اس لیے دونوں مل کر سب سے زیادہ بچت دیتے ہیں۔ پہلے ری سائز کریں، کیونکہ اس سے کمپریسر کو کم پکسلز پر کام کرنا پڑتا ہے۔</p>\n<p>فائل سائز جانچنے کے لیے ہر قدم کے بعد سائز دیکھیں۔ اگر فائل اب بھی بڑی ہو تو اگلا قدم کریں۔</p>\n<h2 id=\"how-each-affects-quality\">ہر قدم معیار پر کیسے اثر ڈالتا ہے</h2>\n<p>ری سائز چھوٹا کرنا معیار کو کم نقصان پہنچاتا ہے، کیونکہ تفصیل ضائع ہونے کا احساس کم ہوتا ہے۔ ری سائز بڑا کرنا معیار کو بہت نقصان پہنچاتا ہے۔</p>\n<p>کمپریشن ہلکی ہو تو معیار برقرار رہتا ہے، بھاری ہو تو رنگوں کی پٹیاں بنتی ہیں۔ معیار 80 سے اوپر رکھیں، تاکہ نقصان نظر نہ آئے۔</p>\n<p>دونوں کو ہلکا رکھیں: تھوڑا ری سائز اور تھوڑی کمپریشن، دونوں کا مجموعہ بہترین نتیجہ دیتا ہے۔</p>\n<h2 id=\"when-to-resize-only\">صرف ری سائز کب کریں</h2>\n<p>جب تصویر بہت بڑی ہو اور منزل کو چھوٹی تصویر چاہیے ہو تو صرف ری سائز کریں۔ مثال کے طور پر، تھمب نیل کے لیے 4000 پکسلز والی تصویر کو 400 پکسلز تک چھوٹا کریں۔</p>\n<p>جب فائل پہلے ہی ہلکی ہو تو بھی صرف ری سائز کافی ہے۔ کمپریشن کی ضرورت نہیں، کیونکہ فائل پہلے ہی چھوٹی ہے۔</p>\n<p>صرف ری سائز اس وقت بھی کافی ہے جب تصویر کو پرنٹ کرنا ہو اور معیار برقرار رکھنا ہو۔</p>\n<h2 id=\"when-to-compress-only\">صرف کمپریس کب کریں</h2>\n<p>جب تصویر کے ابعاد درست ہوں مگر فائل بھاری ہو تو صرف کمپریس کریں۔ مثال کے طور پر، 1920 پکسلز والی 2MB تصویر کو 80 معیار پر 300KB بنائیں۔</p>\n<p>جب تصویر کو اسی سائز میں دکھانا ہو تو بھی صرف کمپریس کریں۔ ابعاد بدلنے سے تصویر کا ڈیزائن خراب ہو جاتا ہے۔</p>\n<p>صرف کمپریس اس وقت بھی کافی ہے جب فائل تھوڑی سی بڑی ہو اور ہلکی کمپریشن کافی ہو۔</p>\n<h2 id=\"when-to-do-both\">دونوں کب کریں</h2>\n<p>جب تصویر بہت بڑی اور بہت بھاری ہو تو دونوں کریں۔ زیادہ تر ویب تصویروں کے لیے دونوں کی ضرورت ہوتی ہے۔</p>\n<p>دونوں کرنے سے فائل سب سے زیادہ ہلکی ہوتی ہے اور تصویر بھی تیز رہتی ہے۔ یہ ویب سائٹ کے لیے بہترین طریقہ ہے۔</p>\n<p>دونوں کرتے وقت پہلے ری سائز کریں، پھر کمپریس کریں۔ الٹی ترتیب سے معیار دو بار گرتا ہے۔</p>\n<h2 id=\"which-order\">کس ترتیب میں: پہلے ری سائز، پھر کمپریس</h2>\n<p>پہلے ری سائز کریں، کیونکہ اس سے کمپریسر کو کم پکسلز پر کام کرنا پڑتا ہے۔ پھر کمپریس کریں، تاکہ بچے ہوئے پکسلز کی فائل ہلکی ہو۔</p>\n<p>الٹی ترتیب میں کمپریس شدہ فائل کو ری سائز کرنے سے معیار دو بار گرتا ہے۔ پہلے کمپریشن تفصیل پھینکتی ہے، پھر ری سائز باقی تفصیل کو سکڑتا ہے۔</p>\n<p>ترتیب یاد رکھیں: کراپ، ری سائز، کمپریس۔ یہی ایڈیٹنگ کی درست ترتیب ہے۔</p>\n<h2 id=\"resizing-compressing-and-the-web\">ری سائز، کمپریس اور ویب</h2>\n<p>ویب کے لیے دونوں ضروری ہیں: ری سائز سے تصویر دکھائی دینے والے سائز کی بنتی ہے، اور کمپریشن سے فائل ہلکی ہوتی ہے۔ دونوں مل کر صفحہ تیز کرتے ہیں۔</p>\n<p>ویب تصویر کے لیے 1920 پکسلز اور 80 معیار بہترین ہے۔ ہیرو کے لیے 1920 اور تھمب نیل کے لیے 400 پکسلز چنیں۔</p>\n<p>ویب کے لیے WebP بھی دیکھیں، جو JPG سے چھوٹی فائل دیتا ہے۔ فارمیٹ بدلنے سے بھی رفتار بڑھتی ہے۔</p>\n<h2 id=\"resizing-compressing-and-print\">ری سائز، کمپریس اور پرنٹ</h2>\n<p>پرنٹ کے لیے ری سائز اہم ہے، کمپریشن کم۔ پرنٹ کو ابعاد اور ڈی پی آئی چاہیے، فائل سائز کی پروا کم ہے۔</p>\n<p>پرنٹ کے لیے معیار 90 سے اوپر رکھیں، کیونکہ کاغذ پر ہلکا نقصان بھی نظر آتا ہے۔ پرنٹ میں کمپریشن کم رکھیں۔</p>\n<p>پرنٹ سے پہلے ابعاد اور ڈی پی آئی جانچیں۔ چھوٹی تصویر بڑے کاغذ پر دھندلی نکلے گی، چاہے کمپریشن کتنی ہلکی ہو۔</p>\n<h2 id=\"common-myths\">عام غلط فہمیاں</h2>\n<p>ایک غلط فہمی یہ ہے کہ کمپریشن ابعاد بدلتی ہے۔ حقیقت یہ ہے کہ کمپریشن صرف وزن بدلتی ہے، ابعاد وہی رہتے ہیں۔</p>\n<p>دوسری غلط فہمی یہ ہے کہ ری سائز فائل کو ہمیشہ ہلکا کرتا ہے۔ اگر کمپریشن خراب ہو تو چھوٹی تصویر بھی بھاری فائل بن سکتی ہے۔</p>\n<p>تیسری غلط فہمی یہ ہے کہ ایک ہی کافی ہے۔ اکثر دونوں کی ضرورت ہوتی ہے، اور دونوں مل کر بہترین نتیجہ دیتے ہیں۔</p>\n<h2 id=\"decision-checklist\">فیصلہ سازی کی جانچ فہرست</h2>\n<p>پہلے منزل کا سائز دیکھیں، پھر فائل کا سائز دیکھیں۔ اگر ابعاد بڑے ہوں تو ری سائز کریں، اگر فائل بھاری ہو تو کمپریس کریں۔ اگر دونوں بڑے ہوں تو دونوں کریں۔</p>\n<p>آخر میں نتیجہ کو مکمل سائز میں دیکھیں اور فائل کا سائز جانچیں۔ اگر دونوں درست ہوں تو کام مکمل ہے۔</p>\n<p>ری سائز کی مکمل رہنمائی <a href=\"/ur/blog/tasveer-resizer-rehnumai/\">امیج ری سائزر رہنما</a> میں، بلک ری سائز <a href=\"/ur/blog/bulk-tasveer-resizer-rehnumai/\">بلک ری سائزر رہنما</a> میں، اور عملی مراحل <a href=\"/ur/blog/tasveer-kaise-resize-karein/\">تصویر کیسے ری سائز کریں</a> میں دیکھیں۔ ویب کے لیے <a href=\"/ur/website-ke-liye-tasveer-optimize-karein/\">ویب امیج آپٹیمائزر</a> استعمال کریں۔</p>\n";

